 const low=new T.Mesh(d.kind==='asteroid'?this.rock:this.sphereLow,surface);low.scale.copy(mesh.scale);const lod=new T.LOD();lod.addLevel(mesh,0);lod.addLevel(low,150);group.add(lod);mesh.userData.id=d.id;
 
 const glow=new T.Mesh(this.sphereLow,new T.ShaderMaterial({uniforms:{tint:{value:color}},vertexShader:'varying vec3 n;void main(){n=normalize(normalMatrix*normal);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 n;uniform vec3 tint;void main(){float a=pow(1.-abs(n.z),4.);gl_FragColor=vec4(tint,a*.4);}',transparent:true,depthWrite:false,blending:T.AdditiveBlending}));glow.scale.setScalar(d.size*(d.kind==='star'?1.2:1.025));group.add(glow);
