 for(const b of this.bodies){this.hitSphere.center.copy(b.group.position);this.hitSphere.radius=b.data.size*1.12;const hit=this.ray.ray.intersectSphere(this.hitSphere,this.hitPoint);if(hit){const distance=hit.distanceTo(this.camera.position);if(distance<depth){depth=distance;nearest=b.data.id}}}
