 c.addEventListener('pointermove',e=>{if(this.focused)return;const action=this.gestures.move(e.pointerId,e.clientX,e.clientY);if(!action){if(e.pointerType==='mouse'&&performance.now()-hoverAt>100){hoverAt=performance.now();const hit=this.pick(e.clientX,e.clientY),d=this.data.find(x=>x.id===hit?.id);c.title=hit?.encounter?'Travelling archive · catch a mathematical curiosity':d?`${d.name} · ${d.kind} · ${d.concept}`:'';c.style.cursor=d?'pointer':'grab'}return}this.destination=null;this.tracking=null;if(action.type==='travel'){this.scrollVelocity=Math.max(-65,Math.min(65,this.scrollVelocity-action.zoom*1.6));this.panVelocity.x=Math.max(-45,Math.min(45,this.panVelocity.x-action.panX*.9));this.panVelocity.y=Math.max(-45,Math.min(45,this.panVelocity.y+action.panY*.9));this.onTravel()}else{this.lookYaw-=action.x*.0024;this.lookPitch=Math.max(-1.35,Math.min(1.35,this.lookPitch-action.y*.0024));if(action.moved)this.onTravel()}});
