 focus(id,encounter=null){this.tracking=null;if(!this.focused)this.savedPose={position:this.camera.position.clone(),yaw:this.lookYaw,pitch:this.lookPitch};this.stop();this.selectionRing.visible=false;this.focused=true;const d=this.data.find(x=>x.id===id);const target=this.living.target(id,encounter);this.destination=target.clone().add(new T.Vector3(0,0,encounter?12:d.size*5));this.lookYaw=0;this.lookPitch=0;this.labelTick=1;this.markers.forEach(el=>el.hidden=true)}
